  Object.entries(state.recipeRatings||{}).filter(([,value])=>Number(value)>0).forEach(([recipeId,rating])=>{const id=familyFeedbackId(recipeId,state.currentUser);if(!state.recipeFeedback.some(item=>item.id===id))state.recipeFeedback.push(touch({id,recipeId,person:state.currentUser,rating:Number(rating)}))});
