function ingredientParts(item){if(Array.isArray(item))return{name:String(item[0]||'').trim(),quantity:String(item[1]||'nach Bedarf').trim()};if(item&&typeof item==='object')return{name:String(item.name||'').trim(),quantity:String(item.quantity||'nach Bedarf').trim()};const text=String(item||'').trim(),match=text.match(/^([\d½¼¾.,]+(?:\s*(?:g|kg|ml|l|EL|TL|Stück(?:e)?|Stk|Dose(?:n)?|Bund|Packung(?:en)?|Päckchen|Zehe(?:n)?|Streifen|Kopf|Köpfe|Schuss|Prise(?:n)?|Becher|Glas|Gläser))?)\s+(.+)$/i);return match?{name:match[2].trim(),quantity:match[1].trim()}:{name:text,quantity:'nach Bedarf'}}
