function renderWeekCalendar(){
  const host=$('#monthCalendar');if(!host)return;host.className='week-calendar';host.innerHTML='';const start=mondayOf(calendarCursor),end=addDays(start,6),sameMonth=start.getMonth()===end.getMonth();
  $('#monthTitle').textContent=sameMonth?`${start.toLocaleDateString('de-DE',{day:'2-digit'})}.–${end.toLocaleDateString('de-DE',{day:'2-digit',month:'long',year:'numeric'})}`:`${start.toLocaleDateString('de-DE',{day:'2-digit',month:'short'})} – ${end.toLocaleDateString('de-DE',{day:'2-digit',month:'short',year:'numeric'})}`;
  for(let index=0;index<7;index++){const date=addDays(start,index),day=document.createElement('section');day.className=`week-day${isoDate(date)===isoDate(today)?' today':''}`;day.innerHTML=`<header><strong>${date.toLocaleDateString('de-DE',{weekday:'long'})}</strong><span>${date.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</span></header><div class="day-items"></div>`;appendCalendarItems($('.day-items',day),date,8,true);if(!$('.day-items',day).children.length)$('.day-items',day).innerHTML='<small>Keine Termine</small>';host.append(day)}bindCalendarSwipe(host);
}
