const shoppingCategoryOrder=['Obst & Gemüse','Backwaren','Fleisch, Fisch & Veggie','Kühlung & Molkerei','Tiefkühl','Frühstück & Vorrat','Kochen, Soßen & Gewürze','Süßes & Snacks','Getränke','Haushalt & Drogerie','Sonstiges'];
function shoppingCategory(name){
  const value=String(name||'').toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(/tomatenmark|dose|konserve|bruhe|fond|sosse|sauce|ketchup|senf|mayonnaise|essig|gewurz|salz|pfeffer|curry|paprika pulver|krauter/.test(value))return'Kochen, Soßen & Gewürze';
  if(/apfel|banane|birne|beere|erdbeer|himbeer|blaubeer|orange|mandarine|zitrone|limette|traube|melone|mango|ananas|kiwi|avocado|salat|tomat|mohre|karotte|gurke|paprika|zwiebel|knoblauch|kartoffel|susskartoffel|brokkoli|blumenkohl|zucchini|aubergine|kurbis|pilz|champignon|spinat|kohl|lauch|sellerie|radies|kraut|kresse|petersilie|schnittlauch|basilikum|koriander|ingwer|peperoni|chili|gemuse|obst/.test(value))return'Obst & Gemüse';
  if(/brot|brotchen|toast|baguette|croissant|backware|wrap|tortilla|knackebrot/.test(value))return'Backwaren';
  if(/tiefkuhl|tiefgefroren|\btk\b|eiscreme|speiseeis|pizza tief/.test(value))return'Tiefkühl';
  if(/hahnchen|huhn|pute|fleisch|rind|kalb|schwein|hack|wurst|schinken|speck|fisch|lachs|thunfisch|forelle|garnele|shrimp|scampi|tofu|tempeh|seitan|veggie|falafel/.test(value))return'Fleisch, Fisch & Veggie';
  if(/milch|kase|joghurt|yogurt|skyr|quark|sahne|butter|margarine|frischkase|mozzarella|feta|parmesan|ei\b|eier|kefir|pudding|hummus/.test(value))return'Kühlung & Molkerei';
  if(/wasser|saft|cola|limonade|limo|bier|wein|sekt|kaffeegetrank|energy|sirup/.test(value))return'Getränke';
  if(/schokolade|keks|chips|gummibar|bonbon|snack|popcorn|cracker|praline/.test(value))return'Süßes & Snacks';
  if(/waschmittel|spulmittel|reiniger|kuchenrolle|toilettenpapier|mullbeutel|backpapier|alufolie|frischhaltefolie|seife|shampoo|zahnpasta|deo|windel|drogerie|haushalt/.test(value))return'Haushalt & Drogerie';
  if(/reis|nudel|pasta|spaghetti|mehl|zucker|hafer|musli|cornflakes|couscous|bulgur|quinoa|linse|bohne|kichererbse|nuss|mandel|sesam|kern|ol\b|olivenol|honig|marmelade|aufstrich/.test(value))return'Frühstück & Vorrat';
  return'Sonstiges';
}
function addShoppingItem(name,quantity='1',source='Manuell'){
  const key=normalizeIngredientName(name),existing=state.shoppingItems.find(item=>normalizeIngredientName(item.name)===key&&!item.done);
  if(existing){existing.quantity=existing.quantity===quantity?existing.quantity:formatCombinedQuantity([existing.quantity,quantity]);existing.source=[...new Set([...(existing.source||'').split(', ').filter(Boolean),source])].join(', ');touch(existing)}else state.shoppingItems.push(touch({id:`shop-${Date.now()}-${Math.random()}`,name,quantity,category:shoppingCategory(name),done:false,source}));save();updateShoppingCount();
}
function updateShoppingCount(){const badge=$('#shoppingCount');if(badge)badge.textContent=state.shoppingItems.filter(item=>!item.done).length}
function renderShoppingList(){
  const host=$('#shoppingList');if(!host)return;host.innerHTML='';state.shoppingItems.forEach(item=>item.category=shoppingCategory(item.name));const groups=shoppingCategoryOrder.filter(category=>state.shoppingItems.some(item=>item.category===category));
  groups.forEach(category=>{const section=document.createElement('section');section.className='shopping-group';section.innerHTML=`<h3>${category}</h3><div></div>`;state.shoppingItems.filter(item=>item.category===category).sort((a,b)=>Number(a.done)-Number(b.done)||a.name.localeCompare(b.name,'de')).forEach(item=>{const row=document.createElement('label');row.className=`shopping-item${item.done?' done':''}`;row.innerHTML=`<input type="checkbox" ${item.done?'checked':''}><span class="checkmark"></span><span class="shopping-name"></span><strong></strong><small></small><button type="button" aria-label="Löschen">×</button>`;$('.shopping-name',row).textContent=item.name;$('strong',row).textContent=item.quantity;$('small',row).textContent=item.source;$('input',row).onchange=e=>{item.done=e.target.checked;touch(item);save();renderShoppingList();updateShoppingCount()};$('button',row).onclick=e=>{e.preventDefault();moveToTrash('shoppingItems',item,'Einkauf');state.shoppingItems=state.shoppingItems.filter(x=>x.id!==item.id);save();renderShoppingList();updateShoppingCount()};$('div',section).append(row)});host.append(section)});
  if(!state.shoppingItems.length)host.innerHTML='<div class="task-empty">Die Einkaufsliste ist leer. Füge etwas hinzu oder übernimm Zutaten aus einem Rezept.</div>';
}
function addRecipeToShopping(recipe){recipe.ingredients.forEach(([name,quantity])=>addShoppingItem(name,quantity,recipe.title));toast(`${recipe.ingredients.length} Zutaten zur Einkaufsliste hinzugefügt`)}
function nutritionFlags(item){const nutrition=item?.nutrition||estimatedVideoNutrition(item||{}),kcal=Number(nutrition?.kcal)||0,protein=Number(nutrition?.protein)||0,fat=Number(nutrition?.fat)||0,carbs=Number(nutrition?.carbs)||0,proteinShare=kcal?protein*4/kcal:0;return {highProtein:protein>=30||proteinShare>=.25,balanced:kcal>=250&&kcal<=650&&protein>=20&&fat<=28&&carbs<=85}}
function nutritionBadges(item){const flags=nutritionFlags(item);return `${flags.highProtein?'<span class="food-badge protein">💪 High Protein</span>':''}${flags.balanced?'<span class="food-badge balanced">🥗 Ausgewogen</span>':''}`}
function recipeRating(id){return Math.max(0,Math.min(5,Number(state.recipeRatings[id])||0))}
function familyFeedbackId(recipeId,person=state.currentUser){return `recipe-feedback-${normalizeIngredientName(person).replace(/\s+/g,'-')}-${String(recipeId).replace(/[^a-z0-9_-]/gi,'-')}`}
function familyRecipeRating(recipeId){const entries=(state.recipeFeedback||[]).filter(item=>item.recipeId===recipeId&&Number(item.rating)>0);return entries.length?{value:entries.reduce((sum,item)=>sum+Number(item.rating),0)/entries.length,count:entries.length}:{value:0,count:0}}
function isPoorlyRated(id){const rating=recipeRating(id);return rating>0&&rating<=2}
function ratingMarkup(item){const rating=recipeRating(item.id),familyRating=familyRecipeRating(item.id);return `<div class="recipe-rating"><span>${rating?`Deine Bewertung: ${rating}/5`:'Rezept bewerten'}${familyRating.count?` · Familie: ${familyRating.value.toFixed(1)}/5`:''}</span><div>${[1,2,3,4,5].map(value=>`<button type="button" data-rate-recipe="${escapeHtml(item.id)}" data-rating="${value}" class="${value<=rating?'active':''}" aria-label="${value} von 5 Sternen">★</button>`).join('')}</div></div>`}
function saveRecipeRating(id,value){const rating=Math.max(1,Math.min(5,Number(value)||1)),feedbackId=familyFeedbackId(id,state.currentUser);state.recipeRatings[id]=rating;const existing=state.recipeFeedback.find(item=>item.id===feedbackId);if(existing)touch(Object.assign(existing,{recipeId:id,person:state.currentUser,rating}));else state.recipeFeedback.push(touch({id:feedbackId,recipeId:id,person:state.currentUser,rating}));recordActivity('bewertet','Rezept',`${rating}/5 Sterne`);save();toast(rating<=2?'Rezept ausgeblendet · ein neues ist nachgerückt':`Rezept mit ${rating} Sternen bewertet`)}
function matchesFoodFilter(item,filter,favorites=[]){if(filter==='hidden')return isPoorlyRated(item.id);if(isPoorlyRated(item.id))return false;if(filter==='favorites')return favorites.includes(item.id);const flags=nutritionFlags(item);if(filter==='protein')return flags.highProtein;if(filter==='balanced')return flags.balanced;return true}
function recipeFilterText(item){const ingredients=item.ingredients||item.recipe?.ingredients||[];return `${item.title||''} ${(item.tags||[]).join(' ')} ${ingredients.flat?.(2).join(' ')||ingredients.join?.(' ')||''}`.toLocaleLowerCase('de')}
function matchesIngredientFilter(item,filter){if(filter==='all')return true;const text=recipeFilterText(item),hasFullIngredients=(item.ingredients?.length||item.recipe?.ingredients?.length||0)>=2;const meatOrFish=/hähn|huhn|chicken|pute|truthahn|rind|beef|kalb|hackfleisch|hack |gehackt|schwein|pork|speck|bacon|schinken|wurst|lamm|fisch|lachs|thunfisch|forelle|kabeljau|seelachs|garnele|shrimp|scampi|meeresfr|sardine|anchovi/.test(text);if(filter==='chicken')return /hähn|huhn|chicken|pute|truthahn/.test(text);if(filter==='beef')return /rind|beef|kalb/.test(text);if(filter==='mince')return /hackfleisch|hack |gehackt|minced/.test(text);if(filter==='pork')return /schwein|pork|speck|bacon|schinken|wurst/.test(text);if(filter==='fish')return /fisch|lachs|thunfisch|forelle|kabeljau|seelachs|garnele|shrimp|scampi|meeresfr|sardine|anchovi/.test(text);if(filter==='vegan'){if(/vegan|pflanzlich/.test(text))return true;return hasFullIngredients&&!meatOrFish&&!/ei\b|eier|milch|käse|quark|joghurt|skyr|sahne|butter|honig/.test(text)}if(filter==='vegetarian')return /vegetar|veggie|fleischlos/.test(text)||(hasFullIngredients&&!meatOrFish);if(filter==='pasta')return /nudel|pasta|spaghetti|penne|lasagne|tagliatelle|tortellini/.test(text);if(filter==='rice')return /reis|rice|risotto/.test(text);if(filter==='potato')return /kartoffel|potato/.test(text);return true}
const ingredientFilterOptions='<option value="all">Alle Hauptzutaten</option><option value="chicken">🍗 Hähnchen & Pute</option><option value="beef">🥩 Rind</option><option value="mince">🍳 Hackfleisch</option><option value="pork">🥓 Schwein</option><option value="fish">🐟 Fisch & Meeresfrüchte</option><option value="vegetarian">🥕 Vegetarisch</option><option value="vegan">🌱 Vegan</option><option value="pasta">🍝 Nudeln</option><option value="rice">🍚 Reis</option><option value="potato">🥔 Kartoffeln</option>';
function allRecipes(){const items=[...state.customRecipes,...recipes];if(state.recipeSort==='default')return items;return items.sort((a,b)=>{const first=state.watchedRecipes.includes(a.id)?1:0;const second=state.watchedRecipes.includes(b.id)?1:0;return state.recipeSort==='watched'?second-first:first-second})}
