function youtubeUrl(value,channelOnly=false){try{const url=new URL(value);const host=url.hostname.replace(/^www\./,'');if(!['youtube.com','m.youtube.com','youtu.be'].includes(host))return'';if(channelOnly&&host==='youtu.be')return'';if(channelOnly&&!/^\/(?:@|channel\/|c\/|user\/)/.test(url.pathname))return'';return url.href}catch{return''}}
function channelNameFromUrl(value){try{const url=new URL(value),part=decodeURIComponent(url.pathname.split('/').filter(Boolean).pop()||'YouTube');return part.replace(/^@/,'')||'YouTube'}catch{return'YouTube'}}
function publicWebsiteUrl(value){try{const url=new URL(value);if(url.protocol!=='https:'||/^(?:localhost|127\.|10\.|192\.168\.)/.test(url.hostname))return'';return url.href}catch{return''}}
function websiteNameFromUrl(value){try{return new URL(value).hostname.replace(/^www\./,'').split('.')[0].replace(/^./,letter=>letter.toUpperCase())}catch{return'Rezeptseite'}}
