function trashAttachmentEntity(collection,itemId){return collection==='tasks'?`task:${itemId}`:collection==='events'?`event:${itemId}`:collection==='customRecipes'?`recipe-cover:${itemId}`:''}
async function restoreTrashItem(id,options={}){const entry=state.trashItems.find(item=>item.id===id);if(!entry||!Array.isArray(state[entry.collection]))return false;const restored=JSON.parse(JSON.stringify(entry.item)),originalId=restored.id,newId=`${originalId}-restored-${Date.now()}-${Math.random().toString(36).slice(2,5)}`;restored.id=newId;restored.restoredFrom=originalId;touch(restored);const oldEntity=trashAttachmentEntity(entry.collection,originalId),newEntity=trashAttachmentEntity(entry.collection,newId);let copied=0;if(oldEntity&&newEntity){try{const files=await getAttachments(oldEntity);for(const file of files){const upload=typeof File==='function'?new File([file.blob],file.name,{type:file.type}):file.blob;await storeAttachments(newEntity,[upload]);copied++}}catch(error){console.error('Anhänge konnten nicht kopiert werden',error)}}state[entry.collection].push(restored);if(entry.collection==='customRecipes'&&copied&&!state.recipePhotoIds.includes(newId))state.recipePhotoIds.push(newId);state.trashItems=state.trashItems.filter(item=>item.id!==id);if(!state.deletedIds.includes(id))state.deletedIds.push(id);recordActivity('wiederhergestellt',restored.title||restored.name||entry.label,`${entry.label}${copied?` · ${copied} Anhänge kopiert`:''}`);if(options.save!==false)save();if(options.render!==false)switchView('trash');if(options.notify!==false)toast(copied?'Eintrag und Anhänge wurden wiederhergestellt':'Eintrag wurde sicher wiederhergestellt');return true}
