function deleteTrashItem(id){const entry=state.trashItems.find(item=>item.id===id);if(!entry||!confirm('Diesen Eintrag endgültig löschen?'))return;state.trashItems=state.trashItems.filter(item=>item.id!==id);if(!state.deletedIds.includes(id))state.deletedIds.push(id);recordActivity('endgültig gelöscht',entry.item.title||entry.item.name||entry.label,entry.label);save();switchView('trash');toast('Eintrag wurde endgültig gelöscht')}
