    Object.assign(state,payload,mergedCollections,{deletedIds});
    Object.assign(state,localPreferences);
    family=Array.isArray(state.familyMembers)&&state.familyMembers.length?[...state.familyMembers]:family;
    setDeviceUser(deviceUser);
    ensureFeatureState();const repaired=lastDataRepairReport.repaired,imported=importTimeTreeCalendar();syncCleaningTasks();
    localStorage.setItem('fami-state',JSON.stringify(state));saveDevicePreferences();if(imported||repaired)window.FamiCloud?.schedulePush(sharedState());
